// Pixel art engine: draw sprites pixel-by-pixel into a buffer, then auto-outline and blit to canvas.
// All game art is generated by code at boot (no external image files needed).

export type Color = number; // 0xRRGGBB, or -1 for transparent

export const T = -1;

export function rgb(c: Color): [number, number, number] {
  return [(c >> 16) & 255, (c >> 8) & 255, c & 255];
}

export function mix(a: Color, b: Color, t: number): Color {
  const [r1, g1, b1] = rgb(a);
  const [r2, g2, b2] = rgb(b);
  const r = Math.round(r1 + (r2 - r1) * t);
  const g = Math.round(g1 + (g2 - g1) * t);
  const bl = Math.round(b1 + (b2 - b1) * t);
  return (r << 16) | (g << 8) | bl;
}

export const lighten = (c: Color, t: number) => mix(c, 0xffffff, t);
export const darken = (c: Color, t: number) => mix(c, 0x000000, t);
/** Hue-shifted shading: shadows drift toward purple, highlights toward warm yellow (classic pixel-art ramp). */
export const shadeDark = (c: Color, t: number) => mix(c, 0x1a0f2e, t);
export const shadeLight = (c: Color, t: number) => mix(c, 0xfff2c0, t);

export function hex(c: Color): string {
  return '#' + c.toString(16).padStart(6, '0');
}

export class PixelCanvas {
  readonly px: Int32Array;
  constructor(public readonly w: number, public readonly h: number) {
    this.px = new Int32Array(w * h).fill(T);
  }

  get(x: number, y: number): Color {
    x |= 0; y |= 0;
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return T;
    return this.px[y * this.w + x];
  }

  set(x: number, y: number, c: Color) {
    x = Math.round(x); y = Math.round(y);
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
    this.px[y * this.w + x] = c;
  }

  rect(x: number, y: number, w: number, h: number, c: Color) {
    for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) this.set(x + i, y + j, c);
  }

  /** Rect with top highlight and bottom/right shadow. */
  shadedRect(x: number, y: number, w: number, h: number, c: Color) {
    this.rect(x, y, w, h, c);
    this.rect(x, y, w, 1, shadeLight(c, 0.3));
    this.rect(x, y + h - 1, w, 1, shadeDark(c, 0.35));
    this.rect(x + w - 1, y + 1, 1, h - 1, shadeDark(c, 0.25));
  }

  ellipse(cx: number, cy: number, rx: number, ry: number, c: Color) {
    for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++) {
      for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x++) {
        const dx = (x + 0.5 - cx) / (rx + 0.01);
        const dy = (y + 0.5 - cy) / (ry + 0.01);
        if (dx * dx + dy * dy <= 1) this.set(x, y, c);
      }
    }
  }

  /** Ellipse lit from the top-left with a 4-tone ramp and specular dot. */
  shadedEllipse(cx: number, cy: number, rx: number, ry: number, c: Color, spec = true) {
    for (let y = Math.floor(cy - ry); y <= Math.ceil(cy + ry); y++) {
      for (let x = Math.floor(cx - rx); x <= Math.ceil(cx + rx); x++) {
        const dx = (x + 0.5 - cx) / (rx + 0.01);
        const dy = (y + 0.5 - cy) / (ry + 0.01);
        const d = dx * dx + dy * dy;
        if (d > 1) continue;
        // light direction (-0.6,-0.7)
        const l = -(dx * -0.55 + dy * -0.75);
        let col = c;
        if (l > 0.45 || d > 0.8 && l > 0.1) col = shadeDark(c, 0.38);
        else if (l > 0.1) col = shadeDark(c, 0.16);
        else if (l < -0.55) col = shadeLight(c, 0.35);
        else if (l < -0.25) col = shadeLight(c, 0.15);
        this.set(x, y, col);
      }
    }
    if (spec && rx >= 3 && ry >= 3) {
      this.set(cx - rx * 0.45, cy - ry * 0.5, lighten(c, 0.75));
      if (rx >= 5) this.set(cx - rx * 0.45 + 1, cy - ry * 0.5, lighten(c, 0.55));
    }
  }

  line(x0: number, y0: number, x1: number, y1: number, c: Color) {
    x0 = Math.round(x0); y0 = Math.round(y0); x1 = Math.round(x1); y1 = Math.round(y1);
    const dx = Math.abs(x1 - x0), dy = -Math.abs(y1 - y0);
    const sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
    let err = dx + dy;
    for (let n = 0; n < 512; n++) {
      this.set(x0, y0, c);
      if (x0 === x1 && y0 === y1) break;
      const e2 = 2 * err;
      if (e2 >= dy) { err += dy; x0 += sx; }
      if (e2 <= dx) { err += dx; y0 += sy; }
    }
  }

  /** Scanline polygon fill. */
  poly(pts: [number, number][], c: Color | ((x: number, y: number) => Color)) {
    const ys = pts.map(p => p[1]);
    const y0 = Math.floor(Math.min(...ys)), y1 = Math.ceil(Math.max(...ys));
    for (let y = y0; y <= y1; y++) {
      const yc = y + 0.5;
      const xs: number[] = [];
      for (let i = 0; i < pts.length; i++) {
        const [ax, ay] = pts[i], [bx, by] = pts[(i + 1) % pts.length];
        if ((ay <= yc && by > yc) || (by <= yc && ay > yc)) xs.push(ax + ((yc - ay) / (by - ay)) * (bx - ax));
      }
      xs.sort((a, b) => a - b);
      for (let k = 0; k + 1 < xs.length; k += 2) {
        for (let x = Math.round(xs[k]); x < Math.round(xs[k + 1]); x++) this.set(x, y, typeof c === 'function' ? c(x, y) : c);
      }
    }
  }

  thickLine(x0: number, y0: number, x1: number, y1: number, c: Color, w = 2) {
    const len = Math.max(1, Math.hypot(x1 - x0, y1 - y0));
    const nx = -(y1 - y0) / len, ny = (x1 - x0) / len;
    for (let i = 0; i < w; i++) {
      const o = i - (w - 1) / 2;
      this.line(x0 + nx * o, y0 + ny * o, x1 + nx * o, y1 + ny * o, c);
    }
  }

  /** Adds a 1px outline into transparent pixels next to opaque ones. Uses darkened neighbor colour for a soft "selout" look. */
  outline(color: Color = 0x1a1020, selout = true) {
    const out = new Int32Array(this.px);
    for (let y = 0; y < this.h; y++) {
      for (let x = 0; x < this.w; x++) {
        if (this.px[y * this.w + x] !== T) continue;
        let n: Color = T;
        const nb = [this.get(x, y - 1), this.get(x - 1, y), this.get(x + 1, y), this.get(x, y + 1)];
        for (const c of nb) if (c !== T) { n = c; break; }
        if (n !== T) out[y * this.w + x] = selout ? mix(darken(n, 0.72), color, 0.5) : color;
      }
    }
    this.px.set(out);
  }

  /** Copy another canvas onto this one (transparent pixels skipped). */
  stamp(src: PixelCanvas, ox: number, oy: number, flipX = false) {
    for (let y = 0; y < src.h; y++) for (let x = 0; x < src.w; x++) {
      const c = src.px[y * src.w + x];
      if (c !== T) this.set(ox + (flipX ? src.w - 1 - x : x), oy + y, c);
    }
  }

  /** Recolour every pixel by function. */
  map(fn: (c: Color, x: number, y: number) => Color) {
    for (let y = 0; y < this.h; y++) for (let x = 0; x < this.w; x++) {
      const i = y * this.w + x;
      if (this.px[i] !== T) this.px[i] = fn(this.px[i], x, y);
    }
  }

  drawTo(ctx: CanvasRenderingContext2D, ox: number, oy: number, alpha = 1) {
    const img = ctx.createImageData(this.w, this.h);
    const d = img.data;
    for (let i = 0; i < this.px.length; i++) {
      const c = this.px[i];
      if (c === T) continue;
      d[i * 4] = (c >> 16) & 255;
      d[i * 4 + 1] = (c >> 8) & 255;
      d[i * 4 + 2] = c & 255;
      d[i * 4 + 3] = Math.round(255 * alpha);
    }
    // putImageData ignores compositing, so go via a temp canvas to preserve existing pixels
    const tmp = document.createElement('canvas');
    tmp.width = this.w; tmp.height = this.h;
    tmp.getContext('2d')!.putImageData(img, 0, 0);
    ctx.drawImage(tmp, ox, oy);
  }
}

/** Build a frame strip: draws `frames` canvases side by side. */
export function stripCanvas(frames: PixelCanvas[]): HTMLCanvasElement {
  const fw = frames[0].w, fh = frames[0].h;
  const c = document.createElement('canvas');
  c.width = fw * frames.length; c.height = fh;
  const ctx = c.getContext('2d')!;
  frames.forEach((f, i) => f.drawTo(ctx, i * fw, 0));
  return c;
}
